/// The sign of the predicate for explicit points, from the first stage that
/// decides.
///
/// Runs [`filter`] with `e = 0.0`, then [`exact_differences`], then
/// [`expansions_translated`], then [`expansions_untranslated`]. `None` means
/// that no stage can decide.
#[inline]
pub fn staged(p: [&[f64; 3]; 4]) -> Option<Sign> {
    filter(p, 0.0)
        .or_else(|| exact_differences(p))
        .or_else(|| expansions_translated(p))
        .or_else(|| expansions_untranslated(p))
}

/// The larger of `a` and `b`, or `b` if they are unordered.
#[inline]
fn max(a: f64, b: f64) -> f64 {
    if a > b { a } else { b }
}

/// Whether `x` is zero or has a magnitude in `min..=max`; false for NaN and
/// infinities.
fn in_range(x: f64, (min, max): (f64, f64)) -> bool {
    x == 0.0 || (min..=max).contains(&x.abs())
}

/// Writes the expansion of `x * y` to `out` and returns its length: the sum of
/// the scalings of `y` by each component of `x`, each scaling written to
/// `scaled`, the partial sums alternating between `spare` and `out`.
fn product(x: &[f64], y: &[f64], scaled: &mut [f64], spare: &mut [f64], out: &mut [f64]) -> usize {
    let Some((&first, rest)) = x.split_first() else {
        return 0;
    };
    // Start so that the last partial sum is written to `out`.
    let (mut partial, mut next) = if rest.len() % 2 == 0 {
        (out, spare)
    } else {
        (spare, out)
    };
    let mut length = expansion::scale(y, first, partial);
    for &component in rest {
        let scaled_length = expansion::scale(y, component, scaled);
        length = expansion::sum(&partial[..length], &scaled[..scaled_length], next);
        core::mem::swap(&mut partial, &mut next);
    }
    length
}
